from pathlib import Path
import ast,hashlib,os,shutil,time
EXPECTED='build_oad_325_solana_BULK_IDEMPOTENT_READBACK_FOUNDATIONAL_REPAIR_V2.py'
TARGET=Path("qseries_v2/oracle_adapters/independent/oad_325_solana_universal_single_writer_persistence.py")
TEST=Path("test_oad_325_solana_bulk_idempotent_readback_foundational_repair_v2.py")
EXPECTED_SHA256='3b744c90cf14c2568e5b69aa360f84742199976c1fc39560ec14b0891d80e665'
NEW_SOURCE='\\\n\nfrom __future__ import annotations\nfrom dataclasses import dataclass\nfrom pathlib import Path\nfrom qseries_v2.oracle_production_hardening.oph_019_postgresql_universal_ingestion_queue import submit_observation_batch,await_request,connect\nfrom .oad_322_solana_universal_chain_coverage_gate import build_universal_coverage_batch\nREAD_ONLY=True;PROBABILITY_ENABLED=False;DIRECTION_ENABLED=False;PUBLICATION_ALLOWED=False;EXECUTION_AUTHORITY=False\nPRODUCER="oracle.solana_universal_chain";PRIORITY=20\n@dataclass(frozen=True,slots=True)\nclass SolanaUniversalPersistenceResult:\n    transactions:int;observations:int;committed_events:int;request_id:str|None;coverage_state:str;execution_authority:bool=False\n\ndef _bulk_existing_observation_ids(observation_ids,root=None,chunk_size=1000):\n    ids=tuple(dict.fromkeys(str(x) for x in observation_ids))\n    if not ids:return frozenset()\n    found=set()\n    with connect(root,connect_timeout_seconds=5.0) as conn:\n        with conn.cursor() as cur:\n            cur.execute("SET LOCAL statement_timeout = \'15000ms\'")\n            for start in range(0,len(ids),int(chunk_size)):\n                chunk=ids[start:start+int(chunk_size)]\n                cur.execute(\n                    "SELECT observation_id FROM oracle_canonical_observations WHERE observation_id = ANY(%s)",\n                    (list(chunk),),\n                )\n                found.update(str(row[0]) for row in cur.fetchall())\n    return frozenset(found)\n\ndef persist_solana_universal_chain_batch(start_slot=None,limit=2,root=None,timeout_seconds=120.0,acquisition_timeout_seconds=20.0):\n    root=Path(root or Path.cwd()).resolve()\n    x=build_universal_coverage_batch(start_slot,limit,acquisition_timeout_seconds)\n    items=tuple(x.observations)\n    if not items:return SolanaUniversalPersistenceResult(x.transactions,0,0,None,x.state,False)\n    ids=tuple(obs.observation_id for obs in items)\n    existing=_bulk_existing_observation_ids(ids,root)\n    missing=tuple(obs for obs in items if obs.observation_id not in existing)\n    request_id=None\n    if missing:\n        sub=submit_observation_batch(PRODUCER,PRIORITY,missing,root)\n        request_id=str(sub.request_id)\n        events=tuple(await_request(request_id,root,float(timeout_seconds)))\n        accepted=tuple(e for e in events if getattr(e,"accepted",False) is True)\n        if len(accepted)!=len(missing):\n            raise RuntimeError("Solana universal single-writer commit mismatch")\n    after=_bulk_existing_observation_ids(ids,root)\n    if len(after)!=len(set(ids)) or any(oid not in after for oid in ids):\n        raise RuntimeError("Solana universal exact PostgreSQL bulk readback mismatch")\n    return SolanaUniversalPersistenceResult(x.transactions,len(items),len(after),request_id,x.state,False)\n'
TEST_SOURCE='import unittest\nfrom types import SimpleNamespace\nimport qseries_v2.oracle_adapters.independent.oad_325_solana_universal_single_writer_persistence as m\n\nclass Obs:\n    def __init__(self,oid): self.observation_id=oid\n\nclass FakeCursor:\n    def __init__(self,existing): self.existing=existing; self.rows=[]; self.select_calls=0\n    def __enter__(self): return self\n    def __exit__(self,*a): return False\n    def execute(self,sql,args=None):\n        if sql.startswith("SET LOCAL"): return\n        if "WHERE observation_id = ANY" in sql:\n            self.select_calls+=1\n            ids=args[0]; self.rows=[(x,) for x in ids if x in self.existing]; return\n        raise AssertionError(sql)\n    def fetchall(self): return list(self.rows)\n\nclass FakeConn:\n    def __init__(self,existing,cursors): self.existing=existing; self.cursors=cursors\n    def __enter__(self): return self\n    def __exit__(self,*a): return False\n    def cursor(self):\n        c=FakeCursor(self.existing); self.cursors.append(c); return c\n\nclass T(unittest.TestCase):\n    def setUp(self):\n        self.orig={k:getattr(m,k) for k in ("build_universal_coverage_batch","connect","submit_observation_batch","await_request")}\n    def tearDown(self):\n        for k,v in self.orig.items(): setattr(m,k,v)\n    def test_bulk_reader_uses_one_connection_and_chunked_queries(self):\n        cursors=[]; existing={"0","500","1000","1499"}\n        m.connect=lambda *a,**k:FakeConn(existing,cursors)\n        found=m._bulk_existing_observation_ids(tuple(str(i) for i in range(1500)),".",chunk_size=1000)\n        self.assertEqual(found,existing); self.assertEqual(len(cursors),1); self.assertEqual(cursors[0].select_calls,2)\n    def test_all_existing_skips_writer_and_bulk_verifies(self):\n        items=tuple(Obs(x) for x in ("a","b","c")); existing={"a","b","c"}; cursors=[]\n        m.build_universal_coverage_batch=lambda *a,**k:SimpleNamespace(observations=items,transactions=3,state="UNIVERSAL_BATCH_ACCOUNTED")\n        m.connect=lambda *a,**k:FakeConn(existing,cursors)\n        m.submit_observation_batch=lambda *a,**k:(_ for _ in ()).throw(AssertionError("writer should not run"))\n        m.await_request=lambda *a,**k:()\n        x=m.persist_solana_universal_chain_batch(100,1,".")\n        self.assertEqual(x.committed_events,3); self.assertIsNone(x.request_id); self.assertEqual(len(cursors),2)\n    def test_mixed_replay_submits_only_missing_then_bulk_readback(self):\n        items=tuple(Obs(x) for x in ("a","b","c")); existing={"a","c"}; cursors=[]; submitted=[]\n        m.build_universal_coverage_batch=lambda *a,**k:SimpleNamespace(observations=items,transactions=3,state="UNIVERSAL_BATCH_ACCOUNTED")\n        m.connect=lambda *a,**k:FakeConn(existing,cursors)\n        def submit(prod,pri,obs,root):\n            submitted.extend(x.observation_id for x in obs); existing.update(submitted); return SimpleNamespace(request_id="r1")\n        m.submit_observation_batch=submit\n        m.await_request=lambda *a,**k:(SimpleNamespace(accepted=True),)\n        x=m.persist_solana_universal_chain_batch(100,1,".")\n        self.assertEqual(submitted,["b"]); self.assertEqual(x.committed_events,3); self.assertEqual(x.request_id,"r1")\n\nif __name__=="__main__":\n    rr=unittest.TextTestRunner(verbosity=2).run(unittest.defaultTestLoader.loadTestsFromTestCase(T))\n    if not rr.wasSuccessful(): raise SystemExit(1)\n    print("[PASS] OAD-325 bulk idempotent readback foundational repair certified")\n    print("[PASS] no per-observation PostgreSQL N+1 read path")\n    print("[PASS] bounded bulk pre-read and exact bulk post-readback")\n'

def atomic(path,src):
    ast.parse(src,filename=str(path)); tmp=path.with_suffix(path.suffix+".tmp"); tmp.write_text(src,encoding="utf-8",newline="\n"); os.replace(tmp,path)

def main():
    if Path(__file__).name!=EXPECTED: raise RuntimeError("installer filename mismatch")
    root=Path.cwd().resolve(); target=root/TARGET
    if not target.is_file(): raise RuntimeError("OAD-325 missing")
    current=target.read_text(encoding="utf-8")
    actual=hashlib.sha256(current.encode()).hexdigest()
    if actual!=EXPECTED_SHA256: raise RuntimeError("exact current OAD-325 repaired source mismatch; no mutation performed: "+actual)
    ast.parse(NEW_SOURCE,filename=str(target)); ast.parse(TEST_SOURCE,filename=str(TEST))
    stamp=time.strftime("%Y%m%dT%H%M%S"); bak=target.with_name(target.name+".pre_bulk_readback_v2."+stamp+".bak"); shutil.copy2(target,bak)
    atomic(target,NEW_SOURCE); atomic(root/TEST,TEST_SOURCE)
    print("[PASS] exact current OAD-325 repaired source hash matched")
    print("[PASS] rollback backup:",bak.relative_to(root))
    print("[PASS] per-observation OAD-068 N+1 read path removed from Solana persistence hot path")
    print("[PASS] bulk observation-id lookup uses one PostgreSQL connection per read phase")
    print("[PASS] lookup chunk size=1000; PostgreSQL statement timeout=15s")
    print("[PASS] missing-only writes still use OPH-019/021 canonical single writer")
    print("[PASS] full-slot bulk readback required before checkpoint-eligible success")
    print("[PASS] canonical duplicate constraints unchanged")
    print("[PASS] no direct write bypass; no second writer; no GMGN dependency")
